t', height);\n\t\t\t\t}\n\t\t\t\tif (blur) {\n\t\t\t\t\turlObj.searchParams.set('blur', blur);\n\t\t\t\t}\n\n\t\t\t\tconst isDevMode = window.location.pathname.indexOf('&devMode=true') !== -1;\n\t\t\t\tif (isDevMode) {\n\t\t\t\t\turlObj.searchParams.set('ci_info', '1');\n\t\t\t\t}\n\n\t\t\t\treturn urlObj.toString();\n\t\t\t},\n\t\t\t_removeImageParams: function(url, paramsToRemove) {\n\t\t\t\ttry {\n\t\t\t\t\tconst urlObj = new URL(url);\n\t\t\t\t\tconst params = urlObj.searchParams;\n\n\t\t\t\t\tparamsToRemove.forEach(param => {\n\t\t\t\t\t\tparams.delete(param);\n\t\t\t\t\t});\n\n\t\t\t\t\treturn urlObj.toString();\n\t\t\t\t} catch (e) {\n\t\t\t\t\tconsole.warn('Invalid URL provided to _removeImageParams:', url);\n\t\t\t\t\treturn url;\n\t\t\t\t}\n\t\t\t},\n\t\t},\n\t}\n\t, videoLib: {\n\t\ttoCdnUrl: function ({ videoUrl, quality }) {\n\t\t\tif (!videoUrl) return videoUrl;\n\n\t\t\tconst forceImgix = buildfire.getContext()?.forceImgix;\n\t\t\tif (!forceImgix) {\n\t\t\t\treturn videoUrl;\n\t\t\t}\n\n\t\t\tconst imgixUrl = `https://buildfire-proxy.imgix.net/cdn/${encodeURIComponent(videoUrl)}`;\n\t\t\tconst urlObj = new URL(imgixUrl);\n\n\t\t\tif (quality) {\n\t\t\t\turlObj.searchParams.set('q', quality);\n\t\t\t}\n\t\t\turlObj.searchParams.set('fm', 'mp4');\n\n\t\t\treturn urlObj.toString()\n\t\t},\n\t\ttoThumbnailCdnUrl: function ({ videoUrl, atSecond = 'auto' }) {\n\t\t\tif (!videoUrl) return '';\n\n\t\t\tconst forceImgix = buildfire.getContext()?.forceImgix;\n\t\t\tif (!forceImgix) {\n\t\t\t\treturn '';\n\t\t\t}\n\n\t\t\tconst imgixUrl = `https://buildfire-proxy.imgix.net/cdn/${encodeURIComponent(videoUrl)}`;\n\t\t\tconst urlObj = new URL(imgixUrl);\n\n\t\t\turlObj.searchParams.set('video-thumbnail', atSecond === 'auto' ? 'auto' : atSecond);\n\t\t\t// urlObj.searchParams.set('q', quality); // uncomment this line and pass quality to set quality for thumbnail images\n\t\t\turlObj.searchParams.set('auto', 'format');\n\n\t\t\treturn urlObj.toString();\n\t\t}\n\t}\n\t, colorLib: {\n\t\tshowDialog: function (data, options, onchange, callback) {\n\t\t\tbuildfire.eventManager.clear('colorLibOnChange');\n\t\t\tif (typeof onchange == 'function') {\n\t\t\t\tbuildfire.eventManager.add('colorLibOnChange', function (data) {\n\t\t\t\t\tonchange(null, data);\n\t\t\t\t}, false);\n\t\t\t}\n\t\t\tvar packetData = {};\n\t\t\tif (options)\n\t\t\t\tpacketData = JSON.parse(JSON.stringify(options));\n\t\t\tpacketData.data = data;\n\n\t\t\tvar p = new Packet(null, 'colorLib.showDialog', packetData);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t},\n\t\t_triggerOnChange: function (data) {\n\t\t\tbuildfire.eventManager.trigger('colorLibOnChange', data);\n\t\t}\n\t}\n\t/// ref: https://github.com/BuildFire/sdk/wiki/How-to-use-Notifications\n\t, notifications: {\n\t\talert: function (options, callback) {\n\t\t\tconsole.warn('Notifications api is deprecated. Please use dialog api. https://github.com/BuildFire/sdk/wiki/How-to-use-Dialogs');\n\t\t\t//make it compatible with app, cp and the old versions\n\t\t\tif(options && options.buttonName && !options.okButton){\n\t\t\t\toptions.okButton = {text: options.buttonName};\n\t\t\t}\n\t\t\tvar p = new Packet(null, 'notificationsAPI.alert', options);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}\n\t\t, confirm: function (options, callback) {\n\t\t\tconsole.warn('Notifications api is deprecated. Please use dialog api. https://github.com/BuildFire/sdk/wiki/How-to-use-Dialogs');\n\t\t\t//make it compatible with app, cp and the old versions\n\t\t\tif (options && options.buttonLabels) {\n\t\t\t\tif (!options.confirmButton) {\n\t\t\t\t\toptions.confirmButton = {text: options.buttonLabels[0]};\n\t\t\t\t}\n\t\t\t\tif (!options.cancelButton) {\n\t\t\t\t\toptions.cancelButton = {text: options.buttonLabels[1]};\n\t\t\t\t}\n\t\t\t}\n\t\t\tvar p = new Packet(null, 'notificationsAPI.confirm', options);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}\n\t\t, prompt: function (options, callback) {\n\t\t\tvar p = new Packet(null, 'notificationsAPI.prompt', options);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}\n\t\t, beep: function (options, callback) {\n\t\t\tvar p = new Packet(null, 'notificationsAPI.beep', options);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}\n\t\t, vibrate: function (options, callback) {\n\t\t\tvar p = new Packet(null, 'notificationsAPI.vibrate', options);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}, showDialog: function (options, callback) {\n\t\t\tconsole.warn('Notifications api is deprecated. Please use dialog api. https://github.com/BuildFire/sdk/wiki/How-to-use-Dialogs');\n\t\t\tvar p = new Packet(null, 'notificationsAPI.showDialog', options);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}\n\t},\n\tdialog: {\n\t\talert: function (options, callback) {\n\t\t\tvar p = new Packet(null, 'dialogAPI.alert', options);\n\t\t\tbuildfire._sendPacket(p, function () {\n\t\t\t\tif (callback)\n\t\t\t\t\treturn callback(null);\n\t\t\t});\n\t\t},\n\t\tconfirm: function (options, callback) {\n\t\t\tif (!options.confirmButtonText) {\n\t\t\t\toptions.confirmButtonText = 'Confirm';\n\t\t\t}\n\t\t\tvar p = new Packet(null, 'dialogAPI.confirm', options);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t},\n\t\tshow: function (options, callback) {\n\t\t\tvar p = new Packet(null, 'dialogAPI.show', options);\n\n\t\t\tvar actionButtonCallbacks = new Object();\n\n\t\t\tif (options.actionButtons && options.actionButtons.length) {\n\t\t\t\toptions.actionButtons.forEach(function (button) {\n\t\t\t\t\tactionButtonCallbacks[button.text] = button.action;\n\t\t\t\t\tdelete button.action;\n\t\t\t\t});\n\t\t\t}\n\t\t\tbuildfire._sendPacket(p, function (err, result) {\n\t\t\t\tif (result && result.selectedButton) {\n\t\t\t\t\tvar action = actionButtonCallbacks[result.selectedButton.text];\n\t\t\t\t\tif (action)\n\t\t\t\t\t\taction();\n\t\t\t\t\tresult.selectedButton.action = action;\n\t\t\t\t\tcallback && callback(err, result.selectedButton);\n\t\t\t\t} else {\n\t\t\t\t\tcallback && callback(err);\n\t\t\t\t}\n\t\t\t});\n\t\t},\n\t\ttoast: function (options, callback) {\n\t\t\tvar p = new Packet(null, 'dialogAPI.toast', options);\n\t\t\tvar actionButton = new Object();\n\t\t\tif (options.actionButton && options.actionButton.action) {\n\t\t\t\tactionButton = Object.assign(actionButton, options.actionButton);\n\t\t\t\tdelete options.actionButton.action;\n\t\t\t}\n\t\t\tbuildfire._sendPacket(p, function (err, actionClicked) {\n\t\t\t\tif (actionClicked) {\n\t\t\t\t\tactionButton.action && actionButton.action();\n\t\t\t\t\tcallback && callback(err, actionButton);\n\t\t\t\t} else {\n\t\t\t\t\tcallback && callback(err, null);\n\t\t\t\t}\n\t\t\t});\n\t\t}\n\t},\n\tbookmarks: {\n\t\tadd: function(options, callback) {\n\t\t\tvar p = new Packet(null, 'bookmarkAPI.add', options);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t},\n\t\t_getParameterByName: function(name, url) {\n\t\t\tif (!url) url = window.location.href;\n\t\t\tname = name.replace(/[\\[\\]]/g, '\\\\$&');\n\t\t\tvar regex = new RegExp('[?&]' + name + '(=([^&#]*)|&|#|$)'),\n\t\t\t\tresults = regex.exec(url);\n\t\t\tif (!results) return null;\n\t\t\tif (!results[2]) return '';\n\t\t\treturn decodeURIComponent(results[2].replace(/\\+/g, ' '));\n\t\t},\n\t\tget: function(callback) {\n\t\t\tvar param = buildfire.bookmarks._getParameterByName('bookmarkPayload');\n\t\t\tvar bookmark = JSON.parse(param);\n\t\t\tcallback(null, bookmark);\n\t\t},\n\t\tgetAll: function(callback) {\n\t\t\tvar p = new Packet(null, 'bookmarkAPI.getAllFromPlugin');\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t},\n\t\tdelete: function(options, callback) {\n\t\t\tvar p = new Packet(null, 'bookmarkAPI.deleteFromPlugin', options);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}\n\t}\n\t/// ref: https://github.com/BuildFire/sdk/wiki/How-to-use-action-Items\n\t/// also https://github.com/BuildFire/sdk/wiki/BuildFire-Action-Items-Component\n\t, actionItems: {\n\t\tshowDialog: function (actionItem, options, callback) {\n\t\t\tvar p = new Packet(null, 'actionItems.showDialog', {actionItem: actionItem, options: options});\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t},\n\t\texecute: function (actionItem, options, callback) {\n\t\t\tif (typeof options === 'function') callback = options;\n\t\t\tvar p = new Packet(null, 'actionItems.execute', actionItem);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t},\n\t\tlist: function (actionItems, options, callback) {\n\t\t\tvar p = new Packet(null, 'actionItems.list', {actionItems: actionItems, options: options});\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t},\n\t\tcreate: function (action, iconUrl, title) {\n\t\t\tvar actionItem = {\n\t\t\t\taction: action,\n\t\t\t\ticonUrl: iconUrl,\n\t\t\t\ttitle: title\n\t\t\t};\n\n\t\t\treturn actionItem;\n\t\t}\n\t}\n\t/// ref: https://github.com/BuildFire/sdk/wiki/How-to-use-Breadcrumbs\n\t, history: {\n\t\tpush: function (label, options, callback) {\n\t\t\tvar p = new Packet(null, 'history.push', {label: label, options: options, source: 'plugin'});\n            let pushCallback = function(err, result) {\n                buildfire.appearance._updateSafeAreaInsetTop(function() {\n                    if (callback) callback(err, result);\n                });\n            };\n\t\t\tbuildfire._sendPacket(p, pushCallback);\n\t\t},\n\t\tonPop: function (callback, allowMultipleHandlers) {\n            let onPopCallback = function(result) {\n                buildfire.appearance._updateSafeAreaInsetTop(function() {\n                    if (callback) callback(result);\n                })\n            };\n\t\t\treturn buildfire.eventManager.add('historyOnPop', onPopCallback, allowMultipleHandlers);\n\t\t},\n\t\ttriggerOnPop: function (obj) {\n\t\t\tbuildfire.eventManager.trigger('historyOnPop', obj);\n\t\t},\n\t\tpop: function (callback) {\n\t\t\tvar p = new Packet(null, 'history.pop');\n            let popCallback = function(error, result) {\n                buildfire.appearance._updateSafeAreaInsetTop(function() {\n                    if (callback) callback(error, result);\n                });\n            };\n\t\t\tbuildfire._sendPacket(p, popCallback);\n\t\t},\n\t\tget: function (options, callback) {\n\t\t\tvar p = new Packet(null, 'history.get', options);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}\n\t}\n\t/// ref: https://github.com/BuildFire/sdk/wiki/How-to-use-Messaging-to-sync-your-Control-to-Widget\n\t, messaging: {\n\t\tsendMessageToControl: function (data) {\n\t\t\tvar p = new Packet(null, 'messaging.triggerOnNewControlMessage', data);\n\t\t\tbuildfire._sendPacket(p);\n\t\t}\n\t\t, sendMessageToWidget: function (data) {\n\t\t\tvar p = new Packet(null, 'messaging.triggerOnNewWidgetMessage', data);\n\t\t\tbuildfire._sendPacket(p);\n\t\t}\n\t\t, onReceivedMessage: function (message) {\n\t\t\tconsole.info('onReceivedMessage ignored', window.location);\n\t\t},\n\t\ttriggerOnReceivedMessage: function (message) {\n\t\t\tbuildfire.eventManager.trigger('messageReceived', message);\n\t\t\tbuildfire.messaging.onReceivedMessage(message)\n\t\t}\n\t\t, sendMessageToService: function (data) {\n\t\t\tvar p = new Packet(null, 'messaging.sendMessageToService', data);\n\t\t\tbuildfire._sendPacket(p);\n\t\t}\n\t\t, broadcast: function (options) {\n\t\t\tif (!options || !options.message) {\n\t\t\t\tthrow new Error('options.message is required');\n\t\t\t}\n\t\t\tif (options.source) {\n\t\t\t\tthrow new Error('options.source is not allowed');\n\t\t\t}\n\t\t\tbuildfire.getContext(function (err, context) {\n\t\t\t\tlet source = {\n\t\t\t\t\tinstanceId: context.instanceId,\n\t\t\t\t\tpluginId: context.pluginId,\n\t\t\t\t\ttitle: context.title,\n\t\t\t\t\tisWidgetService: buildfire.isWidgetService()\n\t\t\t\t}\n\t\t\t\tlet data = { source: source, message: options.message };\n\t\t\t\tlet p = new Packet(null, 'messaging.broadcast', data);\n\t\t\t\tbuildfire._sendPacket(p);\n\t\t\t});\n\t\t}\n\t\t, onReceivedBroadcast: function (broadcast) {\n\t\t\t/* do not log anything as it will be too noisy */\n\t\t}\n\t}\n\t/// ref: https://github.com/BuildFire/sdk/wiki/Plugin-Instances\n\t, pluginInstance: {\n\t\tshowDialog: function (options, callback) {\n\t\t\tvar p = new Packet(null, 'pluginInstances.showDialog', {options: options});\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}\n\t\t, get: function (ids, callback) {\n\t\t\tvar p = new Packet(null, 'pluginInstances.get', ids);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}\n\t\t/*\n         * options {\n         * title : for searching\n         * , pageIndex : 0\n         * , pageSize: max 20\n         * }\n         * */\n\t\t, search: function (options, callback) {\n\t\t\tvar p = new Packet(null, 'pluginInstances.search', options);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}\n\t\t, showCreatePluginInstancesDialog: function (options, callback) {\n\t\t\tif(typeof(options) == 'function' && !callback){\n\t\t\t\tcallback = options;\n\t\t\t\toptions = {skipPluginInstances : true};\n\t\t\t}else if(options){\n\t\t\t\toptions.skipPluginInstances = true;\n\t\t\t}\n\t\t\tbuildfire.pluginInstance.showDialog(options,callback);\n\t\t}\n\t\t, create: function (options, callback) {\n\t\t\tvar p = new Packet(null, 'pluginInstances.create', options);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}\n\t\t, clone: function (options, callback) {\n\t\t\tvar p = new Packet(null, 'pluginInstances.clone', options);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}\n\t\t, showInstallPluginInstanceDialog: function (options, callback) {\n\t\t\tvar p = new Packet(null, 'pluginInstances.showInstallPluginInstanceDialog', options);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}\n\t}\n\t, developer: {\n\t\tpublish: function(options, callback) {\n\t\t\tvar p = new Packet(null, 'developer.publish', options);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}\n\t}\n\t/// ref: https://github.com/BuildFire/sdk/wiki/Deep-Links\n\t, deeplink: {\n\t\tgetData: function (callback) {\n\t\t\tif (buildfire.deeplink._data) {\n\t\t\t\treturn callback(buildfire.deeplink._data);\n\t\t\t}\n\n\t\t\tvar qs = buildfire.parseQueryString();\n\t\t\tif (qs.dld) {\n\t\t\t\tvar obj = JSON.parse(qs.dld);\n\t\t\t\tbuildfire.deeplink._data = obj;\n\t\t\t\tcallback(obj); /// dld: Deep Link Data\n\t\t\t} else {\n\t\t\t\tcallback(null);\n\t\t\t}\n\t\t},\n\t\ttemplate: {\n\t\t\tget: function (callback) {\n\t\t\t\tvar p = new Packet(null, 'deepLink.getTemplate', {});\n\t\t\t\tbuildfire._sendPacket(p, callback);\n\t\t\t}\n\t\t},\n\t\tsetData: function (obj, options, callback) {\n\t\t\tvar p = new Packet(null, 'deepLink.setData', {data : obj, options: options});\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t}\n\t\t,\n\t\tcreateLink: function (obj) {\n\t\t\tconsole.log('this method is obsolete you have to call deeplink.template.get instead and it will return back the full deep link');\n\t\t\tvar root = 'app' + buildfire._context.appId + '://plugin';\n\t\t\tif (!obj)\n\t\t\t\treturn root;\n\t\t\telse\n\t\t\t\treturn root + '?dld=' + JSON.stringify(obj);\n\t\t},\n\t\tgenerateUrl: function (params, callback) {\n\t\t\tvar p = new Packet(null, 'shortLinks.generate', params);\n\t\t\tbuildfire._sendPacket(p, callback);\n\t\t},\n\t\tregisterDeeplink : function(options, callback) {\n\t\t\tif (!callback) {\n\t\t\t\tcallback = function(err) {\n\t\t\t\t\tif(err) console.error(err);\n\t\t\t\t};\n\t\t\t}\n\t\t\tif(!options) {\n\t\t\t\treturn callback('Missing options parameter', null);\n\t\t\t}\n\t\t\tif(!options.id)  {\n\t\t\t\treturn callback('Missing deeplink id', null);\n\t\t\t}\n\t\t\tif(!options.name) {\n\t\t\t\treturn callback('Missing deeplink name', null);\n\t\t\t}\n\t\t\tif(!options.deeplinkData) {\n\t\t\t\treturn callback('Missing deeplink deeplinkData', null);\n\t\t\t}\n\n\t\t\tvar _self = this;\n\t\t\tbuildfire.getContext(function(err, context) {\n\t\t\t\tif(err) {\n\t\t\t\t\tcallback(err, null);\n\t\t\t\t} else {\n\t\t\t\t\tif(context && context.instanceId && context.pluginId) {\n\t\t\t\t\t\tvar deeplinkItem = {\n\t\t\t\t\t\t\tname: options.name,\n\t\t\t\t\t\t\tdeeplinkId: options.id,\n\t\t\t\t\t\t\timageUrl: options.imageUrl,\n\t\t\t\t\t\t\tdeeplinkData: options.deeplinkData,\n\t\t\t\t\t\t\tpluginInstanceId: context.instanceId,\n\t\t\t\t\t\t\tpluginTypeId: context.pluginId,\n\t\t\t\t\t\t\t_buildfire: {\n\t\t\t\t\t\t\t\tindex: {\n\t\t\t\t\t\t\t\t\tstring1: context.instanceId,\n\t\t\t\t\t\t\t\t\ttext: options.name,\n\t\t\t\t\t\t\t\t\tarray1: [{string1: options.id}]\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t};\n\n\t\t\t\t\t\t_self.getDeeplink(options.id, function(err, result) {\n\t\t\t\t\t\t\tif(err) return callback(err, null);\n\t\t\t\t\t\t\tif(result) {\n\t\t\t\t\t\t\t\tbuildfire.appData.update(result.id, deeplinkItem, '$$deeplinks', callback);\n\t\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\t\tbuildfire.appData.insert(deeplinkItem, '$$deeplinks', false, callback);\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t});\n\t\t\t\t\t} else {\n\t\t\t\t\t\tcallback('no context', null);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t});\n\t\t},\n\t\tgetDeeplink : function(deeplinkId, callback) {\n\t\t\tif(!callback) {\n\t\t\t\treturn console.error('Missing callback parameter');\n\t\t\t}\n\t\t\tbuildfire.getContext(function(err, context) {\n\t\t\t\tif(err) return callback(err, null);\n\t\t\t\tif(context && context.instanceId) {\n\t\t\t\t\tvar searchOptions = {\n\t\t\t\t\t\tfilter : {\n\t\t\t\t\t\t\t'_buildfire.index.string1' : context.instanceId,\n\t\t\t\t\t\t\t'_buildfire.index.array1.string1' : deeplinkId\n\t\t\t\t\t\t}\n\t\t\t\t\t};\n\t\t\t\t\tbuildfire.appData.search(searchOptions, '$$deeplinks', function(err, result) {\n\t\t\t\t\t\tif(err) return callback(err, null);\n\t\t\t\t\t\tif(result) {\n\t\t\t\t\t\t\tcallback(null, result[0]);\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\tcallback(null, null);\n\t\t\t\t\t\t}\n\t\t\t\t\t});\n\t\t\t\t} else {\n\t\t\t\t\tcallback('no context', null);\n\t\t\t\t}\n\t\t\t});\n\t\t},\n\t\tgetAllDeeplinks : function(options, callback) {\n\t\t\tif(!callback) {\n\t\t\t\treturn console.error('Missing callback parameter');\n\t\t\t}\n\t\t\toptions = options || {};\n\t\t\tbuildfire.getContext(function(err, context) {\n\t\t\t\tif(err) {\n\t\t\t\t\tcallback(err, null);\n\t\t\t\t} else {\n\t\t\t\t\tif(context && context.instanceId) {\n\t\t\t\t\t\tvar searchOptions = {\n\t\t\t\t\t\t\tpageSize : options.pageSize,\n\t\t\t\t\t\t\tfilter: {\n\t\t\t\t\t\t\t\t'_buildfire.index.string1' : context.instanceId\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t};\n\t\t\t\t\t\tbuildfire.appData.search(searchOptions, '$$deeplinks', callback);\n\t\t\t\t\t} else {\n\t\t\t\t\t\tcallback('no context', null);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t});\n\t\t},\n\t\tunregisterDeeplink : function(deeplinkId, callback) {\n\t\t\tif (!callback) {\n\t\t\t\tcallback = function(err) {\n\t\t\t\t\tif(err) console.error(err);\n\t\t\t\t};\n\t\t\t}\n\t\t\tthis.getDeeplink(deeplinkId, function(err, result) {\n\t\t\t\tif(err) return callback(err, null);\n\t\t\t\tif(result) {\n\t\t\t\t\tbuildfire.appData.delete(result.id, '$$deeplinks', callback);\n\t\t\t\t} else {\n\t\t\t\t\tcallback('no result found for this deeplink id', null);\n\t\t\t\t}\n\t\t\t});\n\t\t},\n\t\tonUpdate: function (callback, allowMultipleHandlers) {\n\t\t\tbuildfire.eventManager.add('deeplinkOnUpdate', callback, allowMultipleHandlers);\n\t\t},\n\t\ttriggerOnUpdate: function (queryString) {\n\t\t\ttry {\n\t\t\t\tvar qs = buildfire.parseQueryString(decodeURIComponent(queryString));\n\t\t\t\tbuildfire.deeplink._data = JSON.parse(qs.dld);\n\t\t\t} catch (error) {\n\t\t\t\tconsole.error(error);\n\t\t\t\tbuildfire.deeplink._data = queryString;\n\t\t\t}\n\t\t\t// navigating to an already-loaded plugin never reloads the frame, so this is the only place\n\t\t\t// a contract call arriving that way gets dispatched\n\t\t\tif (buildfire.deeplink._data && buildfire.deeplink._data.contractAction) {\n\t\t\t\tbuildfire.deeplink._runContractAction({ deeplinkData: buildfire.deeplink._data });\n\t\t\t}\n\t\t\tbuildfire.eventManager.trigger('deeplinkOnUpdate', buildfire.deeplink._data);\n\t\t},\n\n\t\t/**\n\t\t * \"contractAction\" is a reserved key in the deeplink data: it means the app navigated here to\n\t\t * run one of this plugin's declared contract operations in its own, on-screen frame — it is not\n\t\t * ordinary deeplink data for the plugin to interpret. The SDK dispatches it to\n\t\t * window.widgetContract so every plugin gets identical handling for free.\n\t\t *\n\t\t * Payload shape: { contractAction: { functionName: String, parameters: Object, callId?: String } }\n\t\t * When callId is present the outcome is reported back to the host (contract._dispatchActionResult)\n\t\t * so the caller of buildfire.services.contract.invoke receives the actual result.\n\t\t *\n\t\t * @param {Object} data parsed deeplink data\n\t\t * @returns {Boolean} true when the payload was a contract call (and was handled here)\n\t\t */\n\t\t/**\n\t\t * Run a contract operation delivered in this frame's deeplink data.\n\t\t * @param {Object} options { deeplinkData } — the parsed deeplink data, which carries the call\n\t\t *                          under its reserved \"contractAction\" key\n\t\t * @param {Function} [callback] (err, result) — errors are logged when no callback is given\n\t\t */\n\t\t_runContractAction: function (options, callback) {\n\t\t\toptions = options || {};\n\t\t\tvar contractAction = options.deeplinkData && options.deeplinkData.contractAction;\n\n\t\t\t// The caller is waiting on this operation's actual result: when the call carries a callId, report\n\t\t\t// the outcome back to the host under it (contract._dispatchActionResult), which hands it to the\n\t\t\t// caller's callback. Once only — a plugin that calls back twice must not answer twice.\n\t\t\tvar callId = contractAction && contractAction.callId;\n\t\t\tvar userCallback = callback;\n\t\t\tvar settled = false;\n\t\t\tcallback = function (err, result) {\n\t\t\t\tif (settled) return;\n\t\t\t\tsettled = true;\n\t\t\t\tif (err) console.error(err);\n\t\t\t\tif (callId) {\n\t\t\t\t\t// errors are plain values on the wire — an Error object would arrive as {}\n\t\t\t\t\tvar error = err ? buildfire._serializableError(err) : null;\n\t\t\t\t\ttry {\n\t\t\t\t\t\tbuildfire._sendPacket(new Packet(null, 'contract._dispatchActionResult', {\n\t\t\t\t\t\t\tcallId: callId,\n\t\t\t\t\t\t\terror: error,\n\t\t\t\t\t\t\tresult: result === undefined ? null : result\n\t\t\t\t\t\t}));\n\t\t\t\t\t} catch (postError) {\n\t\t\t\t\t\t// a result postMessage cannot clone: report that, so the caller is not left waiting\n\t\t\t\t\t\tbuildfire._sendPacket(new Packet(null, 'contract._dispatchActionResult', {\n\t\t\t\t\t\t\tcallId: callId,\n\t\t\t\t\t\t\terror: 'contract function \"' + contractAction.functionName + '\" returned a result that cannot be sent back: '\n\t\t\t\t\t\t\t\t+ (postError && postError.message ? postError.message : postError),\n\t\t\t\t\t\t\tresult: null\n\t\t\t\t\t\t}));\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif (typeof (userCallback) === 'function') userCallback(err, result);\n\t\t\t};\n\n\t\t\tif (!contractAction || !contractAction.functionName) return callback('no contract operation in this deeplink');\n\n\t\t\t// Only what the plugin deliberately exposes can be called — a contract cannot reach arbitrary\n\t\t\t// globals. Which namespace depends on where this page was loaded: a control page implements its\n\t\t\t// operations on window.controlContract, a widget page on window.widgetContract. The path is what\n\t\t\t// decides, the same test the contract service uses when it runs a function in a hidden frame.\n\t\t\tvar isControl = window.location && window.location.pathname.indexOf('/control/') >= 0;\n\t\t\tvar namespace = isControl ? 'controlContract' : 'widgetContract';\n\n\t\t\t// the namespace lives in plugin.contract.js, which a plugin has no reason to load on every page\n\t\t\t// view, so fetch it first and come back here once\n\t\t\tif (!window[namespace] && !buildfire.deeplink._contractScriptLoaded) {\n\t\t\t\t// the original callback: the re-run wraps it again, and reports the result itself\n\t\t\t\treturn buildfire.deeplink._ensurePluginContractLoaded(null, function () {\n\t\t\t\t\tbuildfire.deeplink._runContractAction(options, userCallback);\n\t\t\t\t});\n\t\t\t}\n\n\t\t\tvar operation = window[namespace] && window[namespace][contractAction.functionName];\n\t\t\tif (typeof (operation) !== 'function') {\n\t\t\t\treturn callback('contract function \"' + contractAction.functionName + '\" was not found on window.' + namespace);\n\t\t\t}\n\n\t\t\t// the parameters are published as this frame's deeplink data as well as passed as arguments, so\n\t\t\t// a function that reads its deeplink — how most plugins already take input — needs no changes\n\t\t\tif (contractAction.parameters) buildfire.deeplink._data = contractAction.parameters;\n\n\t\t\t// answers once however the function finishes: callback, returned Promise, return value, or throw\n\t\t\tbuildfire._runContractFunction(operation, contractAction.parameters, contractAction.functionName, callback);\n\t\t},\n\n\t\t// Make sure the plugin's own plugin.contract.js has been fetched — it defines\n\t\t// window.widgetContract, and sits beside the page being served, so a relative path works\n\t\t// wherever the plugin is hosted. Already settled means the callback runs straight away.\n\t\t//\n\t\t// Calls that arrive while the fetch is in flight wait for it rather than being turned away — a\n\t\t// second operation must not fail just because the first one started the download.\n\t\t_ensurePluginContractLoaded: function (options, callback) {\n\t\t\tvar deeplink = buildfire.deeplink;\n\t\t\tif (deeplink._contractScriptLoaded) return callback();\n\n\t\t\tdeeplink._contractScriptWaiting.push(callback);\n\t\t\tif (deeplink._contractScriptRequested) return; // already downloading; the queue gets drained below\n\t\t\tdeeplink._contractScriptRequested = true;\n\n\t\t\t// settled either way: a plugin without the file must not leave callers waiting forever\n\t\t\tvar settle = function () {\n\t\t\t\tdeeplink._contractScriptLoaded = true;\n\t\t\t\tvar waiting = deeplink._contractScriptWaiting;\n\t\t\t\tdeeplink._contractScriptWaiting = [];\n\t\t\t\tfor (var i = 0; i < waiting.length; i++) waiting[i]();\n\t\t\t};\n\n\t\t\tvar script = document.createElement('script');\n\t\t\tscript.src = 'contract/plugin.contract.js';\n\t\t\tscript.onload = settle;\n\t\t\tscript.onerror = function () {\n\t\t\t\tconsole.error('this plugin provides no plugin.contract.js to run its contract operations');\n\t\t\t\tsettle();\n\t\t\t};\n\t\t\tdocument.head.appendChild(script);\n\t\t},\n\t\t_contractScriptRequested: false,\n\t\t_contractScriptLoaded: false,\n\t\t_contractScriptWaiting: [],\n\n\t\t_data: null\n\t}\n\t/// ref: https://github.com/BuildFire/sdk/wiki/Spinners\n\t, spinner: {\n\t\tshow: function (options) {\n\t\t\t// TODO: long term fix for workaround to prevent existing plugins with un-intended control calls for spinner.show()\n\t\t\tif (options && options.loadingMessage && window.location.pathname.indexOf('/control/') >= 0) {\n\t\t\t\tbuildfire.spinner._showControlSpinner(options);\n\t\t\t} else {\n\t\t\t\tbuildfire._sendPacket(new Packet(null, 'spinner.show', options));\n\t\t\t}\n\t\t}\n\t\t, hide: function () {\n\t\t\tif (window.location.pathname.indexOf('/control/') >= 0) {\n\t\t\t\tbuildfire.spinner._hideControlSpinner();\n\t\t\t} else {\n\t\t\t\tbuildfire._sendPacket(new Packet(null, 'spinner.hide'));\n\t\t\t}\n\t\t}\n\t\t, _showControlSpinner: function (options) {\n\t\t\tconst animationElement = buildfire.spinner._createAnimationElement(options);\n\t\t\tanimationElement.classList.add('ai-progress-overlay');\n\t\t\tdocument.body.prepend(animationElement);\n\t\t}\n\t\t, _hideControlSpinner: function () {\n\t\t\tconst progressElement = document.querySelector('.ai-progress-overlay');\n\t\t\tif (progressElement) progressElement.parentElement.removeChild(progressElement);\n\t\t}\n\t\t, _createAnimationElement: function (options) {